="doc",args={"CYN那几个大汉围住了你们，看来不解决他们是走不掉了。NOR"}}},autoCondition3={relation="and",conditions={{type="equaltab",args={"318003",4}},{type="inroom",args={"hdroom1813","hdroom1809"}}}},autoResult3={{type="stop",args={}},{type="doc",args={"CYN雪还没停，歇一歇再走吧。NOR"}}},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},hdroom1814={id="hdroom1814",name="客栈后院",permission=1,mapHide="0",dsc="客栈的后院，像是久未打扫，生了不少杂草在其中，两边用石头垒了个不算高的假山。",left="hdroom1813",roomRoles={},roomItems={},BgmDown="1",roomBgm="mache",roomBgmRule=2,stepMusic="jiaobu",fightBackground="城镇室外",autoCondition1={relation="and",conditions={{type="equaltab",args={"318003",4}},{type="inroom",args={"hdroom1813","hdroom1814"}}}},autoResult1={{type="doc",args={"CYN后院中堆着不少货物，上面还染着血渍，有两个人趴在货物上，已经没了呼吸。NOR"}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},hdroom1815={id="hdroom1815",name="荒庙",permission=1,mapHide="0",dsc="有些破败的寺庙，庙中还有尊带着点锈迹的佛像，应该许久没有人打扫了。",left="hdroom1816",right="hdroom1810",roomRoles={},roomItems={},BgmDown="1",roomBgm="mache",roomBgmRule=2,stepMusic="jiaobu",fightBackground="城镇室外",autoCondition1={relation="and",conditions={{type="equaltab",args={"318004",2}},{type="inroom",args={"hdroom1810","hdroom1815"}}}},autoResult1={{type="doc",args={"CYN荒庙中已经有几个人在了，看上去一身和尚的打扮，脸上还有油渍没擦去。NOR"}},{type="doc",args={"CYN他们见你们进来，两眼放光，又装作不在意的互相交流，时不时打量着你们身上的行囊。NOR"}},{type="gaintab",args={"318004",3}},{type="addobject",args={"rw11"}},{type="addobject",args={"rw12"}}},autoCondition2={relation="and",conditions={{type="inroom",args={"hdroom1815","hdroom1810"}},{type="tablt",args={"318004",6}},{type="tabgr",args={"318004",2}}}},autoResult2={{type="sto